audCC:'"[{\"start\":0,\"editorState\":{\"blocks\":[{\"key\":\"5nope\",\"text\":\"SCORM stands for Sharable Content Object Reference Model. It is a standard that allows eLearning courses to communicate with a learning management system, or LMS. A SCORM package contains the files and information needed to launch and track a course. Within a SCORM course are Shareable Content Objects, or SCOs, which send learner data back to the LMS. This allows the LMS to track things like course completion, scores, time, and progress.\",\"type\":\"unstyled\",\"depth\":0,\"inlineStyleRanges\":[{\"offset\":0,\"length\":441,\"style\":\"textShadowBlur:8px\"},{\"offset\":0,\"length\":441,\"style\":\"desktop-fontSize:24\"},{\"offset\":0,\"length\":441,\"style\":\"backgroundColor:unset\"},{\"offset\":0,\"length\":441,\"style\":\"WebkitTextStrokeWidth:1px\"},{\"offset\":0,\"length\":441,\"style\":\"hlnkt:wp\"},{\"offset\":0,\"length\":441,\"style\":\"fontStyle:normal\"},{\"offset\":0,\"length\":441,\"style\":\"mobile-fontSize:24\"},{\"offset\":0,\"length\":441,\"style\":\"defaultTextStrokeWidth:1px\"},{\"offset\":0,\"length\":441,\"style\":\"WebkitTextStrokeColor:#F1EEE6\"},{\"offset\":0,\"length\":441,\"style\":\"textOutlineEnable:false\"},{\"offset\":0,\"length\":441,\"style\":\"opacity:1\"},{\"offset\":0,\"length\":441,\"style\":\"defaultTextStrokeColor:#F1EEE6\"},{\"offset\":0,\"length\":441,\"style\":\"hlnke:true\"},{\"offset\":0,\"length\":441,\"style\":\"defaultTextShadow:none\"},{\"offset\":0,\"length\":441,\"style\":\"tablet-fontSize:24\"},{\"offset\":0,\"length\":441,\"style\":\"textShadow:none\"},{\"offset\":0,\"length\":441,\"style\":\"textShadowX:0px\"},{\"offset\":0,\"length\":441,\"style\":\"fontStretch:normal\"},{\"offset\":0,\"length\":441,\"style\":\"fontType:regular\"},{\"offset\":0,\"length\":441,\"style\":\"color:#ffffff\"},{\"offset\":0,\"length\":441,\"style\":\"defaultBackgroundColor:#E8D01B\"},{\"offset\":0,\"length\":441,\"style\":\"textShadowY:4px\"},{\"offset\":0,\"length\":441,\"style\":\"textShadowColor:#F1EEE61F\"},{\"offset\":0,\"length\":441,\"style\":\"lineHeight:135%\"},{\"offset\":0,\"length\":441,\"style\":\"letterSpacing:0%\"},{\"offset\":0,\"length\":441,\"style\":\"textHighlightEnable:false\"},{\"offset\":0,\"length\":441,\"style\":\"textTransform:none\"},{\"offset\":0,\"length\":441,\"style\":\"textShadowOpacity:none\"},{\"offset\":0,\"length\":441,\"style\":\"overridden:true\"},{\"offset\":0,\"length\":441,\"style\":\"textDecoration:none\"},{\"offset\":0,\"length\":441,\"style\":\"fontFamily:Georgia\"},{\"offset\":0,\"length\":441,\"style\":\"borderBottomStyle:none\"},{\"offset\":0,\"length\":441,\"style\":\"textShadowEnable:false\"},{\"offset\":0,\"length\":441,\"style\":\"hlnk:\"},{\"offset\":0,\"length\":441,\"style\":\"fontWeight:normal\"}],\"entityRanges\":[],\"data\":{\"listDepth\":\"0\",\"listColor\":\"#666666\",\"listIndent\":\"100%\",\"verticalAlign\":\"middle\",\"overridden\":\"true\",\"marginLeft\":\"0px\",\"listType\":\"S_Bullets08\",\"textAlign\":\"center\",\"marginBottom\":\"0%\",\"presetId\":\"text-closedcaptions\",\"listSize\":\"100%\"}}],\"entityMap\":{}},\"CCPosition\":\"BOTTOM\",\"text\":\"SCORM stands for Sharable Content Object Reference Model. It is a standard that allows eLearning courses to communicate with a learning management system, or LMS. A SCORM package contains the files and information needed to launch and track a course. Within a SCORM course are Shareable Content Objects, or SCOs, which send learner data back to the LMS. This allows the LMS to track things like course completion, scores, time, and progress.\",\"duration\":33.1,\"end\":33.1,\"id\":\"caption__3076__7\",\"dirtyReasons\":[],\"speechAgentV1\":{\"name\":\"David Castlemore - Newsreader and Educator\",\"voiceId\":{\"modelId\":\"1\",\"uid\":\"XjLkpWUlnhS8i7gGz3lZ\"},\"source\":\"AIVoices\"}}]"',
