audCC:'"[{\"start\":0,\"editorState\":{\"blocks\":[{\"key\":\"fdr5t\",\"text\":\"SCORM 1.2 and SCORM 2004 both support core tracking, including completion, scores, and progress. SCORM 2004 adds more advanced capabilities, such as additional suspend data, separate completion and success statuses, interaction tracking, sequencing and navigation rules, and support for multiple SCOs. These features make SCORM 2004 better suited for complex learning paths and more detailed reporting.\",\"type\":\"unstyled\",\"depth\":0,\"inlineStyleRanges\":[{\"offset\":0,\"length\":402,\"style\":\"color:#ffffff\"},{\"offset\":0,\"length\":402,\"style\":\"defaultBackgroundColor:#E8D01B\"},{\"offset\":0,\"length\":402,\"style\":\"textShadowY:4px\"},{\"offset\":0,\"length\":402,\"style\":\"textShadowColor:#F1EEE61F\"},{\"offset\":0,\"length\":402,\"style\":\"lineHeight:135%\"},{\"offset\":0,\"length\":402,\"style\":\"letterSpacing:0%\"},{\"offset\":0,\"length\":402,\"style\":\"textHighlightEnable:false\"},{\"offset\":0,\"length\":402,\"style\":\"textTransform:none\"},{\"offset\":0,\"length\":402,\"style\":\"textShadowOpacity:none\"},{\"offset\":0,\"length\":402,\"style\":\"overridden:true\"},{\"offset\":0,\"length\":402,\"style\":\"textDecoration:none\"},{\"offset\":0,\"length\":402,\"style\":\"fontFamily:Georgia\"},{\"offset\":0,\"length\":402,\"style\":\"borderBottomStyle:none\"},{\"offset\":0,\"length\":402,\"style\":\"textShadowEnable:false\"},{\"offset\":0,\"length\":402,\"style\":\"hlnk:\"},{\"offset\":0,\"length\":402,\"style\":\"fontWeight:normal\"},{\"offset\":0,\"length\":402,\"style\":\"textShadowBlur:8px\"},{\"offset\":0,\"length\":402,\"style\":\"desktop-fontSize:24\"},{\"offset\":0,\"length\":402,\"style\":\"backgroundColor:unset\"},{\"offset\":0,\"length\":402,\"style\":\"WebkitTextStrokeWidth:1px\"},{\"offset\":0,\"length\":402,\"style\":\"hlnkt:wp\"},{\"offset\":0,\"length\":402,\"style\":\"fontStyle:normal\"},{\"offset\":0,\"length\":402,\"style\":\"mobile-fontSize:24\"},{\"offset\":0,\"length\":402,\"style\":\"defaultTextStrokeWidth:1px\"},{\"offset\":0,\"length\":402,\"style\":\"WebkitTextStrokeColor:#F1EEE6\"},{\"offset\":0,\"length\":402,\"style\":\"textOutlineEnable:false\"},{\"offset\":0,\"length\":402,\"style\":\"opacity:1\"},{\"offset\":0,\"length\":402,\"style\":\"defaultTextStrokeColor:#F1EEE6\"},{\"offset\":0,\"length\":402,\"style\":\"hlnke:true\"},{\"offset\":0,\"length\":402,\"style\":\"defaultTextShadow:none\"},{\"offset\":0,\"length\":402,\"style\":\"tablet-fontSize:24\"},{\"offset\":0,\"length\":402,\"style\":\"textShadow:none\"},{\"offset\":0,\"length\":402,\"style\":\"textShadowX:0px\"},{\"offset\":0,\"length\":402,\"style\":\"fontStretch:normal\"},{\"offset\":0,\"length\":402,\"style\":\"fontType:regular\"}],\"entityRanges\":[],\"data\":{\"listDepth\":\"0\",\"listColor\":\"#666666\",\"listIndent\":\"100%\",\"verticalAlign\":\"middle\",\"overridden\":\"true\",\"marginLeft\":\"0px\",\"listType\":\"S_Bullets08\",\"textAlign\":\"center\",\"marginBottom\":\"0%\",\"presetId\":\"text-closedcaptions\",\"listSize\":\"100%\"}}],\"entityMap\":{}},\"CCPosition\":\"BOTTOM\",\"text\":\"SCORM 1.2 and SCORM 2004 both support core tracking, including completion, scores, and progress. SCORM 2004 adds more advanced capabilities, such as additional suspend data, separate completion and success statuses, interaction tracking, sequencing and navigation rules, and support for multiple SCOs. These features make SCORM 2004 better suited for complex learning paths and more detailed reporting.\",\"duration\":31.5,\"end\":31.5,\"id\":\"caption__3126__8\",\"dirtyReasons\":[],\"speechAgentV1\":{\"name\":\"David Castlemore - Newsreader and Educator\",\"voiceId\":{\"modelId\":\"1\",\"uid\":\"XjLkpWUlnhS8i7gGz3lZ\"},\"source\":\"AIVoices\"}}]"',
