slideThemeCounter:0,
audCC:'"[{\"start\":0,\"editorState\":{\"blocks\":[{\"key\":\"3h0ho\",\"text\":\"SCORM works well for traditional learning delivered through an LMS, but it has some limitations. It cannot easily track learning that happens outside the LMS, such as coaching or real-world practice. It also has limitations with offline and mobile-first learning, detailed decision paths, custom data, and newer analytics such as video engagement and cross-platform behavior. These limitations created a need for a more flexible way to track learning experiences.\",\"type\":\"unstyled\",\"depth\":0,\"inlineStyleRanges\":[{\"offset\":0,\"length\":463,\"style\":\"color:#ffffff\"},{\"offset\":0,\"length\":463,\"style\":\"defaultBackgroundColor:#E8D01B\"},{\"offset\":0,\"length\":463,\"style\":\"textShadowY:4px\"},{\"offset\":0,\"length\":463,\"style\":\"textShadowColor:#F1EEE61F\"},{\"offset\":0,\"length\":463,\"style\":\"lineHeight:135%\"},{\"offset\":0,\"length\":463,\"style\":\"letterSpacing:0%\"},{\"offset\":0,\"length\":463,\"style\":\"textHighlightEnable:false\"},{\"offset\":0,\"length\":463,\"style\":\"textTransform:none\"},{\"offset\":0,\"length\":463,\"style\":\"textShadowOpacity:none\"},{\"offset\":0,\"length\":463,\"style\":\"overridden:true\"},{\"offset\":0,\"length\":463,\"style\":\"textDecoration:none\"},{\"offset\":0,\"length\":463,\"style\":\"fontFamily:Georgia\"},{\"offset\":0,\"length\":463,\"style\":\"borderBottomStyle:none\"},{\"offset\":0,\"length\":463,\"style\":\"textShadowEnable:false\"},{\"offset\":0,\"length\":463,\"style\":\"hlnk:\"},{\"offset\":0,\"length\":463,\"style\":\"fontWeight:normal\"},{\"offset\":0,\"length\":463,\"style\":\"textShadowBlur:8px\"},{\"offset\":0,\"length\":463,\"style\":\"desktop-fontSize:24\"},{\"offset\":0,\"length\":463,\"style\":\"backgroundColor:unset\"},{\"offset\":0,\"length\":463,\"style\":\"WebkitTextStrokeWidth:1px\"},{\"offset\":0,\"length\":463,\"style\":\"hlnkt:wp\"},{\"offset\":0,\"length\":463,\"style\":\"fontStyle:normal\"},{\"offset\":0,\"length\":463,\"style\":\"mobile-fontSize:24\"},{\"offset\":0,\"length\":463,\"style\":\"defaultTextStrokeWidth:1px\"},{\"offset\":0,\"length\":463,\"style\":\"WebkitTextStrokeColor:#F1EEE6\"},{\"offset\":0,\"length\":463,\"style\":\"textOutlineEnable:false\"},{\"offset\":0,\"length\":463,\"style\":\"opacity:1\"},{\"offset\":0,\"length\":463,\"style\":\"defaultTextStrokeColor:#F1EEE6\"},{\"offset\":0,\"length\":463,\"style\":\"hlnke:true\"},{\"offset\":0,\"length\":463,\"style\":\"defaultTextShadow:none\"},{\"offset\":0,\"length\":463,\"style\":\"tablet-fontSize:24\"},{\"offset\":0,\"length\":463,\"style\":\"textShadow:none\"},{\"offset\":0,\"length\":463,\"style\":\"textShadowX:0px\"},{\"offset\":0,\"length\":463,\"style\":\"fontStretch:normal\"},{\"offset\":0,\"length\":463,\"style\":\"fontType:regular\"}],\"entityRanges\":[],\"data\":{\"listDepth\":\"0\",\"listColor\":\"#666666\",\"listIndent\":\"100%\",\"verticalAlign\":\"middle\",\"overridden\":\"true\",\"marginLeft\":\"0px\",\"listType\":\"S_Bullets08\",\"textAlign\":\"center\",\"marginBottom\":\"0%\",\"presetId\":\"text-closedcaptions\",\"listSize\":\"100%\"}}],\"entityMap\":{}},\"CCPosition\":\"BOTTOM\",\"text\":\"SCORM works well for traditional learning delivered through an LMS, but it has some limitations. It cannot easily track learning that happens outside the LMS, such as coaching or real-world practice. It also has limitations with offline and mobile-first learning, detailed decision paths, custom data, and newer analytics such as video engagement and cross-platform behavior. These limitations created a need for a more flexible way to track learning experiences.\",\"duration\":32.1,\"end\":32.1,\"id\":\"caption__2450__10\",\"dirtyReasons\":[],\"speechAgentV1\":{\"name\":\"David Castlemore - Newsreader and Educator\",\"voiceId\":{\"modelId\":\"1\",\"uid\":\"XjLkpWUlnhS8i7gGz3lZ\"},\"source\":\"AIVoices\"}}]"',
