audCC:'"[{\"start\":0,\"editorState\":{\"blocks\":[{\"key\":\"1u5lg\",\"text\":\"SCORM is designed primarily for courses delivered through a learning management system, with learner data stored in the LMS. Its tracking is based on predefined data fields. xAPI is more flexible. It can track learning experiences that happen in many different environments, and its data is stored in a Learning Record Store, or LRS. This flexibility also allows xAPI to support more detailed and modern learning analytics.\",\"type\":\"unstyled\",\"depth\":0,\"inlineStyleRanges\":[{\"offset\":0,\"length\":423,\"style\":\"color:#ffffff\"},{\"offset\":0,\"length\":423,\"style\":\"defaultBackgroundColor:#E8D01B\"},{\"offset\":0,\"length\":423,\"style\":\"textShadowY:4px\"},{\"offset\":0,\"length\":423,\"style\":\"textShadowColor:#F1EEE61F\"},{\"offset\":0,\"length\":423,\"style\":\"lineHeight:135%\"},{\"offset\":0,\"length\":423,\"style\":\"letterSpacing:0%\"},{\"offset\":0,\"length\":423,\"style\":\"textHighlightEnable:false\"},{\"offset\":0,\"length\":423,\"style\":\"textTransform:none\"},{\"offset\":0,\"length\":423,\"style\":\"textShadowOpacity:none\"},{\"offset\":0,\"length\":423,\"style\":\"overridden:true\"},{\"offset\":0,\"length\":423,\"style\":\"textDecoration:none\"},{\"offset\":0,\"length\":423,\"style\":\"fontFamily:Georgia\"},{\"offset\":0,\"length\":423,\"style\":\"borderBottomStyle:none\"},{\"offset\":0,\"length\":423,\"style\":\"textShadowEnable:false\"},{\"offset\":0,\"length\":423,\"style\":\"hlnk:\"},{\"offset\":0,\"length\":423,\"style\":\"fontWeight:normal\"},{\"offset\":0,\"length\":423,\"style\":\"textShadowBlur:8px\"},{\"offset\":0,\"length\":423,\"style\":\"desktop-fontSize:24\"},{\"offset\":0,\"length\":423,\"style\":\"backgroundColor:unset\"},{\"offset\":0,\"length\":423,\"style\":\"WebkitTextStrokeWidth:1px\"},{\"offset\":0,\"length\":423,\"style\":\"hlnkt:wp\"},{\"offset\":0,\"length\":423,\"style\":\"fontStyle:normal\"},{\"offset\":0,\"length\":423,\"style\":\"mobile-fontSize:24\"},{\"offset\":0,\"length\":423,\"style\":\"defaultTextStrokeWidth:1px\"},{\"offset\":0,\"length\":423,\"style\":\"WebkitTextStrokeColor:#F1EEE6\"},{\"offset\":0,\"length\":423,\"style\":\"textOutlineEnable:false\"},{\"offset\":0,\"length\":423,\"style\":\"opacity:1\"},{\"offset\":0,\"length\":423,\"style\":\"defaultTextStrokeColor:#F1EEE6\"},{\"offset\":0,\"length\":423,\"style\":\"hlnke:true\"},{\"offset\":0,\"length\":423,\"style\":\"defaultTextShadow:none\"},{\"offset\":0,\"length\":423,\"style\":\"tablet-fontSize:24\"},{\"offset\":0,\"length\":423,\"style\":\"textShadow:none\"},{\"offset\":0,\"length\":423,\"style\":\"textShadowX:0px\"},{\"offset\":0,\"length\":423,\"style\":\"fontStretch:normal\"},{\"offset\":0,\"length\":423,\"style\":\"fontType:regular\"}],\"entityRanges\":[],\"data\":{\"listDepth\":\"0\",\"listColor\":\"#666666\",\"listIndent\":\"100%\",\"verticalAlign\":\"middle\",\"overridden\":\"true\",\"marginLeft\":\"0px\",\"listType\":\"S_Bullets08\",\"textAlign\":\"center\",\"marginBottom\":\"0%\",\"presetId\":\"text-closedcaptions\",\"listSize\":\"100%\"}}],\"entityMap\":{}},\"CCPosition\":\"BOTTOM\",\"text\":\"SCORM is designed primarily for courses delivered through a learning management system, with learner data stored in the LMS. Its tracking is based on predefined data fields. xAPI is more flexible. It can track learning experiences that happen in many different environments, and its data is stored in a Learning Record Store, or LRS. This flexibility also allows xAPI to support more detailed and modern learning analytics.\",\"duration\":31.3,\"end\":31.3,\"id\":\"caption__9357__12\",\"dirtyReasons\":[],\"speechAgentV1\":{\"name\":\"David Castlemore - Newsreader and Educator\",\"voiceId\":{\"modelId\":\"1\",\"uid\":\"XjLkpWUlnhS8i7gGz3lZ\"},\"source\":\"AIVoices\"}}]"',
