link:3833,
text:['"[{\"start\":0,\"editorState\":{\"blocks\":[{\"key\":\"2pd2d\",\"text\":\"As learning expanded beyond traditional LMS-hosted courses, there was a need for new ways to track learning experiences. The ADL funded the Tin Can API as a research project to redesign SCORM. Tin Can eventually became the official standard known as xAPI, or Experience API. Unlike SCORM, xAPI was designed to track learning experiences beyond the traditional LMS.\",\"type\":\"unstyled\",\"depth\":0,\"inlineStyleRanges\":[{\"offset\":0,\"length\":364,\"style\":\"textShadowBlur:8px\"},{\"offset\":0,\"length\":364,\"style\":\"desktop-fontSize:24\"},{\"offset\":0,\"length\":364,\"style\":\"backgroundColor:unset\"},{\"offset\":0,\"length\":364,\"style\":\"WebkitTextStrokeWidth:1px\"},{\"offset\":0,\"length\":364,\"style\":\"hlnkt:wp\"},{\"offset\":0,\"length\":364,\"style\":\"fontStyle:normal\"},{\"offset\":0,\"length\":364,\"style\":\"mobile-fontSize:24\"},{\"offset\":0,\"length\":364,\"style\":\"defaultTextStrokeWidth:1px\"},{\"offset\":0,\"length\":364,\"style\":\"WebkitTextStrokeColor:#F1EEE6\"},{\"offset\":0,\"length\":364,\"style\":\"textOutlineEnable:false\"},{\"offset\":0,\"length\":364,\"style\":\"opacity:1\"},{\"offset\":0,\"length\":364,\"style\":\"defaultTextStrokeColor:#F1EEE6\"},{\"offset\":0,\"length\":364,\"style\":\"hlnke:true\"},{\"offset\":0,\"length\":364,\"style\":\"defaultTextShadow:none\"},{\"offset\":0,\"length\":364,\"style\":\"tablet-fontSize:24\"},{\"offset\":0,\"length\":364,\"style\":\"textShadow:none\"},{\"offset\":0,\"length\":364,\"style\":\"textShadowX:0px\"},{\"offset\":0,\"length\":364,\"style\":\"fontStretch:normal\"},{\"offset\":0,\"length\":364,\"style\":\"fontType:regular\"},{\"offset\":0,\"length\":364,\"style\":\"color:#ffffff\"},{\"offset\":0,\"length\":364,\"style\":\"defaultBackgroundColor:#E8D01B\"},{\"offset\":0,\"length\":364,\"style\":\"textShadowY:4px\"},{\"offset\":0,\"length\":364,\"style\":\"textShadowColor:#F1EEE61F\"},{\"offset\":0,\"length\":364,\"style\":\"lineHeight:135%\"},{\"offset\":0,\"length\":364,\"style\":\"letterSpacing:0%\"},{\"offset\":0,\"length\":364,\"style\":\"textHighlightEnable:false\"},{\"offset\":0,\"length\":364,\"style\":\"textTransform:none\"},{\"offset\":0,\"length\":364,\"style\":\"textShadowOpacity:none\"},{\"offset\":0,\"length\":364,\"style\":\"overridden:true\"},{\"offset\":0,\"length\":364,\"style\":\"textDecoration:none\"},{\"offset\":0,\"length\":364,\"style\":\"fontFamily:Georgia\"},{\"offset\":0,\"length\":364,\"style\":\"borderBottomStyle:none\"},{\"offset\":0,\"length\":364,\"style\":\"textShadowEnable:false\"},{\"offset\":0,\"length\":364,\"style\":\"hlnk:\"},{\"offset\":0,\"length\":364,\"style\":\"fontWeight:normal\"}],\"entityRanges\":[],\"data\":{\"listDepth\":\"0\",\"listColor\":\"#666666\",\"listIndent\":\"100%\",\"verticalAlign\":\"middle\",\"overridden\":\"true\",\"marginLeft\":\"0px\",\"listType\":\"S_Bullets08\",\"textAlign\":\"center\",\"marginBottom\":\"0%\",\"presetId\":\"text-closedcaptions\",\"listSize\":\"100%\"}}],\"entityMap\":{}},\"CCPosition\":\"BOTTOM\",\"text\":\"As learning expanded beyond traditional LMS-hosted courses, there was a need for new ways to track learning experiences. The ADL funded the Tin Can API as a research project to redesign SCORM. Tin Can eventually became the official standard known as xAPI, or Experience API. Unlike SCORM, xAPI was designed to track learning experiences beyond the traditional LMS.\",\"duration\":27.5,\"end\":27.5,\"id\":\"caption__8840__11\",\"dirtyReasons\":[],\"speechAgentV1\":{\"name\":\"David Castlemore - Newsreader and Educator\",\"voiceId\":{\"modelId\":\"1\",\"uid\":\"XjLkpWUlnhS8i7gGz3lZ\"},\"source\":\"AIVoices\"}}]"']
